// slots (design D7: never automatic seed-on-first-login). PURE DELEGATION to
// identity.AdoptLegacyRows (3.5): one transaction, newer-wins per item —
// progress by updated_at, watched by completed_at (watched_items carries no
// updated_at; the task-line's "newer-wins-by-updated_at" is the progress
// half of that law) — and slot 0 drains completely, so a rerun is a no-op.
// The response is a bare 204: identity returns no counts and the design
// serves none — the ledger rows themselves are the read-back. Unknown user →
// 404 (AdoptLegacyRows probes before it writes — adoption never mints
// dangling rows).
//
// @Summary     Adopt the user's legacy ledger rows (one-shot)
// @Tags        admin
// @ID          admin-users-adopt-legacy
// @Router      /admin/users/{id}/adopt-legacy [post]
// @Param       id path int true "user id"
// @Success     204 "slot-0 rows merged newer-wins into the user's slots and slot 0 drained; a rerun is a no-op"
// @Failure     400 {object} errorBody "non-integer id"
// @Failure     401 {object} errorBody
// @Failure     403 {object} errorBody
// @Failure     404 {object} errorBody "unknown user id"
// @Failure     500 {object} errorBody
// @Failure     503 {object} errorBody
func (a *app) adminUserAdopt(w http.ResponseWriter, r *http.Request) {
	idsvc, ok := a.identityService()
	if !ok {
		writeError(w, http.StatusServiceUnavailable, "unavailable",
			"admin users endpoint disabled", false)
		return
	}
	id, ok := adminUserID(w, r)
	if !ok {
		return
	}
	u, err := idsvc.UserByID(r.Context(), id)
	if err != nil {
		a.adminUserError(w, err)
		return
	}
	if err := idsvc.AdoptLegacyRows(r.Context(), u.ID); err != nil {
		a.adminUserError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

